<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $result = sd_message_threads(); ?><div class="sd-conversation-list"><div class="sd-message-toolbar"><h2><?php esc_html_e( 'Inbox', 'social-discovery' ); ?></h2><a class="sd-button sd-button-small" href="<?php echo esc_url( sd_messages_nav_url() ); ?>#compose"><?php esc_html_e( 'Compose', 'social-discovery' ); ?></a></div><?php if ( empty( $result['threads'] ) ) : ?><p class="sd-muted"><?php esc_html_e( 'No conversations yet.', 'social-discovery' ); ?></p><?php else : foreach ( $result['threads'] as $thread ) : ?><a class="sd-conversation-link" href="<?php echo esc_url( sd_message_thread_url( $thread->thread_id ) ); ?>"><strong><?php echo esc_html( isset( $thread->last_message ) ? wp_trim_words( wp_strip_all_tags( $thread->last_message->message ), 8 ) : __( 'Conversation', 'social-discovery' ) ); ?></strong><small><?php echo esc_html( isset( $thread->last_message ) ? $thread->last_message->date_sent : '' ); ?></small></a><?php endforeach; endif; ?></div>
